return ['domain'=>'presspermit-pro|| n%100>=20) ? 1 : 2;','plural-forms'=>'nplurals=3; plural=(n == 1 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'pl_PL&& (n % 100 < 10 || n % 100 >= 20) ? 1: 2);','project-id-version'=>'PublishPress Permissions Pro 4.8.1','pot-creation-date'=>'2026-04-02T18:54:49+00:00','po-revision-date'=>'2026-10-01 19:50+0000','x-generator'=>'Weblate 2026.6.1','messages'=>['PublishPress Permissions Pro'=>'PublishPress Permissions Pro','https://publishpress.com/permissions'=>'https://publishpress.com/permissions','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions pozwala na włączenie lub odrzucenie dostępu do postów, stron, kategorii, tagów i nie tylko.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Should pages with privacy status "premium" require set_pages_premium and edit_premium_pages capabilities? If so, you can %1$sassign a status-specific Page Editor role%2$s or %3$sadd the capabilities directly to a role%4$s.'=>'Czy strony z statusem prywatności "premium" powinny wymagać możliwości set_pages_premium i edit_premium_pages? Jeśli tak, możesz %1$sprzydzielić rolę Edytora Stron specyficzną dla statusu%2$s lub %3$sbezpośrednio dodać te możliwości do roli%4$s.','Note: Workflow sequence and branching for pre-publication is configured %son a separate screen%s'=>'Uwaga: Sekwencja i rozgałęzianie workflow dla pre-publikacji jest skonfigurowana %son a separate screen%s','Additional settings provided by the %s module.'=>'Dodatkowe ustawienia dostarczone przez moduł %s.','Note: If you deactive, re-entry of the license key will be required for re-activation.'=>'Uwaga: Jeśli dezaktywujesz, ponowne wprowadzenie klucza licencyjnego będzie wymagane do ponownej aktywacji.','If enabled, custom group membership is applied network-wide (though role assignments are still site-specific).'=>'Jeśli włączone, członkostwo w grupach niestandardowych jest stosowane w całej sieci (choć przypisania ról są nadal specyficzne dla witryny).','Can create network-wide permission groups'=>'Może tworzyć grupy uprawnień w całej sieci','If group editing is allowed, can also modify network group membership'=>'Jeśli edytowanie grup jest dozwolone, może również modyfikować członkostwo grupy w sieci','This feature will control direct URL access to files in /uploads/ folder. By default, files are blocked if they are attached to a post which the user can\'t view.'=>'Funkcja ta będzie kontrolować bezpośredni dostęp URL do plików w folderze /uploads/. Domyślnie pliki są zablokowane, jeśli są dołączone do posta, którego użytkownik nie może zobaczyć.','File Access on multisite installations will require the following rules to be inserted above the stock ms-files.php rules in the %1$smain .htaccess file%2$s:'=>'Dostęp do plików w instalacjach multisite będzie wymagał wstawienia następujących reguł powyżej standardowych reguł ms-files.php w pliku %1$smain .htaccess%2$s:','But your .htaccess is missing or not writeable!'=>'Ale Twój plik .htaccess jest brakujący lub nie jest zapisywalny!','.htaccess needs to be updated to include these rules.'=>'Plik .htaccess musi zostać zaktualizowany, aby uwzględnić te reguły.','.htaccess file has all required rules.'=>'Plik .htaccess zawiera wszystkie wymagane reguły.','These rules will not be inserted automatically.  You are responsible for editing .htaccess and later removing the rules if the functionality is no longer desired.'=>'Te reguły nie będą wstawiane automatycznie. Jesteś odpowiedzialny za edytowanie pliku .htaccess i późniejsze usunięcie reguł, jeśli funkcjonalność nie jest już pożądana.','Note that an additional rule will need to be added with each new site. %1$sTo eliminate this requirement, research "WordPress remove ms-files".%2$s'=>'Uwaga, że z każdą nową witryną będzie trzeba dodać dodatkową regułę. %1$sAby wyeliminować ten wymóg, poszukaj "WordPress remove ms-files".%2$s','You will need to manually restore the .htacces file to default contents if anything goes wrong. Proceed?'=>'Będziesz musiał ręcznie przywrócić plik .htaccess do domyślnej zawartości, jeśli coś pójdzie nie tak. Kontynuować?','Update .htaccess now'=>'Zaktualizuj .htaccess teraz','only for sites with protected files'=>'tylko dla stron z chronionymi plikami','for all sites'=>'dla wszystkich stron','NONE: remove Permissions rules'=>'BRAK: usuń zasady uprawnień','Since the plugin is not network-activated, you will need to modify the .htaccess file manually, inserting a RewriteRule as shown above for each site which needs file filtering.'=>'Ponieważ wtyczka nie jest aktywowana w sieci, będziesz musiał ręcznie zmodyfikować plik .htaccess, wstawiając RewriteRule, jak pokazano powyżej, dla każdej strony, która potrzebuje filtrowania plików.','This extends the File Access feature to files that are not attached to any post. This will not apply to user who have the edit_private_files or pp_list_all_files capability.'=>'To rozszerza funkcję Dostępu do Plików na pliki, które nie są dołączone do żadnego posta. To nie będzie dotyczyć użytkowników, którzy mają uprawnienia edit_private_files lub pp_list_all_files.','Make attached files unreadable to users who do not have the edit_private_files or pp_list_all_files capability.'=>'Uczyń dołączone pliki nieczytelnymi dla użytkowników, którzy nie mają uprawnień edit_private_files lub pp_list_all_files.','Improve Media Library performance by disabling file filtering for thumbnails (size specified in Settings > Media).'=>'Popraw wydajność Biblioteki Mediów, wyłączając filtrowanie plików dla miniaturek (rozmiar określony w Ustawieniach > Media).','On some sites, an additional redirect is required to correctly deliver protected files. Leave this disabled for better performance if possible.'=>'Na niektórych stronach wymagane jest dodatkowe przekierowanie, aby poprawnie dostarczać chronione pliki. Pozostaw to wyłączone dla lepszej wydajności, jeśli to możliwe.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys (at next site access) that protect the files.'=>'Funkcja Dostępu do Plików używa pliku %1$s.htaccess%2$s znajdującego się w %3$suploads/.htaccess%4$s. Zazwyczaj nie są potrzebne żadne działania, ale kliknięcie przycisku poniżej zaktualizuje klucze URL (przy następnym dostępie do strony), które chronią pliki.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys that protect the files.'=>'Funkcja Dostępu do Plików używa pliku %1$s.htaccess%2$s znajdującego się w %3$suploads/.htaccess%4$s. Zazwyczaj nie są potrzebne żadne działania, ale kliknięcie przycisku poniżej zaktualizuje klucze URL, które chronią pliki.','Best practice is to access the above url periodically (using your own cron service) to prevent long-term bookmarking of protected files.'=>'Najlepszą praktyką jest okresowy dostęp do powyższego URL (korzystając z własnej usługi cron), aby zapobiec długoterminowemu zakładaniu chronionych plików.','Supply a custom key which will enable a support url to regenerate file access keys.  Then execute the url regularly (using your own cron service) to prevent long-term bookmarking of protected files.'=>'Podaj niestandardowy klucz, który umożliwi adresowi URL wsparcia regenerację kluczy dostępu do plików. Następnie regularnie wykonuj ten adres URL (korzystając z własnej usługi cron), aby zapobiec długoterminowemu zakładaniu chronionych plików.','File Access can also protect files uploaded by FTP or other manual file copy, but does not detect them automatically. Click the button below to scan your uploads folder for files to protect.'=>'Dostęp do Plików może również chronić pliki przesyłane przez FTP lub inną ręczną kopię plików, ale nie wykrywa ich automatycznie. Kliknij przycisk poniżej, aby zeskanować folder przesyłania w poszukiwaniu plików do ochrony.','Invalid file filtering key argument.'=>'Nieprawidłowy argument klucza filtrowania plików.','Please configure File Access options!'=>'Proszę skonfigurować opcje Dostępu do Plików!','The wp-content folder cannot be relocated outside the main WordPress folder.'=>'Folder wp-content nie może być przeniesiony poza główny folder WordPress.','Files linked in post content must be in %1$s (or a subfolder of it). If you move files, consider using a %2$s search and replace plugin%3$s to update those URLs.'=>'Pliki powiązane w treści postów muszą znajdować się w %1$s (lub w jego podfolderze). Jeśli przeniesiesz pliki, rozważ użycie %2$s wtyczki do wyszukiwania i zamiany%3$s, aby zaktualizować te adresy URL.','File Access can also protect files uploaded by FTP or other manual processes, but does not detect them automatically. This utility can find and protect any uploaded files.'=>'Dostęp do Plików może również chronić pliki przesyłane przez FTP lub inne procesy ręczne, ale nie wykrywa ich automatycznie. To narzędzie może znaleźć i chronić wszystkie przesłane pliki.','To run this utility by cron task or other direct request, use the following URL:'=>'Aby uruchomić to narzędzie za pomocą zadania cron lub innego bezpośredniego żądania, użyj następującego adresu URL:','To run this utility by direct URL, set a file filtering regen key on Permissions Settings'=>'Aby uruchomić to narzędzie za pomocą bezpośredniego URL, ustaw klucz filtrujący plików w ustawieniach uprawnień','Note: Direct access to uploaded file attachments cannot be filtered because your WP_CONTENT_DIR is not in the WordPress branch.'=>'Uwaga: Bezpośredni dostęp do przesłanych załączników plików nie może być filtrowany, ponieważ Twój WP_CONTENT_DIR nie znajduje się w gałęzi WordPress.','The operation was terminated due to an invalid configuration.'=>'Operacja została przerwana z powodu nieprawidłowej konfiguracji.','Checking %s posts / pages...'=>'Sprawdzanie %s postów / stron...','%1$s skipping unfilterable file in %2$s "%3$s":%4$s %5$s'=>'%1$s pomijanie pliku, którego nie można filtrować w %2$s "%3$s":%4$s %5$s','%1$s skipping missing file in %2$s "%3$s":%4$s %5$s'=>'%1$s pomijanie brakującego pliku w %2$s "%3$s":%4$s %5$s','%1$sNew attachment in %2$s "%3$s":%4$s %5$s'=>'%1$sNowy załącznik w %2$s "%3$s":%4$s %5$s','%s linked uploads were found in your post / page content.'=>'%s powiązanych przesyłek znaleziono w treści Twojego postu / strony.','%s attachment records were added to the database.'=>'%s rekordów załączników zostało dodanych do bazy danych.','All linked uploads are already registered as attachments.'=>'Wszystkie powiązane przesyłki są już zarejestrowane jako załączniki.','Statuses enabled here are available as Visibility options for post publishing. Affected posts become inaccessable without a corresponding status-specific role assignment.'=>'Statusy włączone tutaj są dostępne jako opcje widoczności przy publikowaniu postów. Dotknięte posty stają się niedostępne bez przypisania odpowiedniej roli specyficznej dla statusu.','Statuses enabled here are available in the editor as additional steps between Draft and Published.'=>'Statusy włączone tutaj są dostępne w edytorze jako dodatkowe kroki między szkicem a opublikowaniem.','Statuses alter your content\'s accessibility by imposing additional capability requirements.'=>'Statusy zmieniają dostępność Twojej treści, nakładając dodatkowe wymagania dotyczące możliwości.','Enable Custom Capabilities by toggling the link below status name. If enabled, non-Editors will need a corresponding %ssupplemental role%s to edit posts of that status.'=>'Włącz niestandardowe uprawnienia, przełączając link poniżej nazwy statusu. Jeśli jest włączone, osoby niebędące Edytorami będą potrzebować odpowiedniej %ssupplemental role%s, aby edytować posty tego statusu.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button increment the post to the next workflow status permitted.'=>'Aby edytować post przez użytkownika, który nie może publikować, %sworkflow jest skonfigurowany%s tak, aby przycisk Publikuj zwiększał post do następnego dozwolonego statusu workflow.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button escalate the post to the highest-ordered workflow status permitted.'=>'Aby edytować post przez użytkownika, który nie może publikować, %sworkflow jest skonfigurowany%s tak, aby przycisk Publikuj eskalował post do najwyżej uporządkowanego dozwolonego statusu workflow.','For post edit by a user who cannot publish, the Publish button will escalate the post to the highest-order status permitted to the user.'=>'Aby edytować post przez użytkownika, który nie może publikować, przycisk Publikuj eskalował post do najwyższego dozwolonego statusu dla użytkownika.','Please enable the PublishPress %sStatuses feature%s.'=>'Proszę włączyć funkcję %sStatusy PublishPress%s.','Note that the Post Type itself will also need to have %sPermissions%s enabled.'=>'Zauważ, że typ postu również musi mieć włączone %sUprawnienia%s.','To disable custom visibility statuses, first re-assign posts to a different status.'=>'Aby wyłączyć niestandardowe statusy widoczności, najpierw przypisz posty do innego statusu.','Note, this only applies if the role definition includes the pp_moderate_any capability'=>'Uwaga, dotyczy to tylko wtedy, gdy definicja roli obejmuje zdolność pp_moderate_any','Create or edit custom Privacy or Workflow statuses.'=>'Utwórz lub edytuj niestandardowe statusy prywatności lub workflow.','Create or edit custom Privacy statuses.'=>'Utwórz lub edytuj niestandardowe statusy prywatności.','Extra Roles created as a type-specific copy of this role will enable assignment of specified custom statuses.'=>'Dodatkowe role utworzone jako specyficzna kopia tej roli umożliwią przypisanie określonych niestandardowych statusów.','Editors do not need status-specific editing capabilities for workflow posts (Assigned, In Progress, Approved).'=>'Redaktorzy nie potrzebują zdolności edytowania specyficznych statusów dla postów workflow (Przydzielony, W trakcie, Zatwierdzony).','If enabled, non-Editors will need to be granted editing access via the "Permissions" screen.'=>'Jeśli włączone, osoby niebędące redaktorami będą musiały otrzymać dostęp do edytowania poprzez ekran "Uprawnienia".','If enabled, a Visibility Status dropdown will appear in Quick Edit for easy status assignment.'=>'Jeśli włączone, w Quick Edit pojawi się rozwijane menu Status Widoczności, aby łatwo przypisać status.','If enabled, this will add Visibility Statuses support to the PublishPress Status plugin.'=>'Jeśli włączone, to doda wsparcie dla Statusów Widoczności do wtyczki PublishPress Status.','Post property or meta field to match with user field'=>'Właściwość posta lub pole meta do dopasowania z polem użytkownika','User property or meta field to match with post field'=>'Właściwość użytkownika lub pole meta do dopasowania z polem posta','User meta field to match with post field'=>'Pole meta użytkownika do dopasowania z polem posta','User role to include in synchronization'=>'Rola użytkownika do uwzględnienia w synchronizacji','Parent id for created posts'=>'Id rodzica dla utworzonych postów','Choose post field from suggested meta key names'=>'Wybierz pole posta z sugerowanych nazw kluczy meta','When a new user of specified role is added, create or designate a post for them.'=>'Gdy nowy użytkownik określonej roli zostanie dodany, utwórz lub wyznacz post dla niego.','Create or designate a post for existing users.'=>'Utwórz lub wyznacz post dla istniejących użytkowników.','This post type is not hierarchical'=>'Ten typ posta nie jest hierarchiczny','Automatically create a post for each user in selected roles.'=>'Automatycznie utwórz post dla każdego użytkownika w wybranych rolach.','Hint: If %s have custom fields (like email address), create one to assist field name discovery.'=>'Wskazówka: Jeśli %s mają niestandardowe pola (np. adres e-mail), utwórz jedno, aby pomóc w odkrywaniu nazw pól.','Enable each user to edit their own User Posts.'=>'Umożliw każdemu użytkownikowi edytowanie swoich własnych Postów Użytkownika.','Settings for replacing unreadable content with teaser text, provided by the %s module.'=>'Ustawienia dotyczące zastępowania nieczytelnych treści tekstem zapowiedzi, dostarczonym przez moduł %s.','Settings on this tab do not apply because teaser filtering is disabled for all post types.'=>'Ustawienia na tej karcie nie mają zastosowania, ponieważ filtrowanie zapowiedzi jest wyłączone dla wszystkich typów postów.','Since some browsers will cache feeds without regard to user login, block RSS content even for qualified users.'=>'Ponieważ niektóre przeglądarki będą buforować kanały, nie zważając na zalogowanego użytkownika, zablokuj treści RSS nawet dla uprawnionych użytkowników.','This feature controls what users will see when trying to view content they are blocked from accessing.'=>'Ta funkcja kontroluje, co użytkownicy zobaczą, próbując uzyskać dostęp do treści, do których nie mają dostępu.','These settings adjust which views, link types and visibility statuses the teaser is applied to.'=>'Te ustawienia dostosowują, do których widoków, typów linków i statusów widoczności stosuje się zapowiedź.','You can override Teaser settings within the Nav Menu by hiding links to unreadable posts that are associated with the terms you select below.'=>'Możesz nadpisać ustawienia zapowiedzi w menu nawigacyjnym, ukrywając linki do nieczytelnych postów związanych z terminami, które wybierzesz poniżej.','Keep unreadable content hidden in the blogroll and link lists, but show the teaser on direct access attempts.'=>'Zachowaj nieczytelne treści w ukryciu w blogrollu i listach linków, ale pokaż zapowiedź podczas prób bezpośredniego dostępu.','Hide unreadable private posts, but show a teaser for posts which are unreadable due to regular Privacy or Role Restrictions.'=>'Ukryj nieczytelne prywatne posty, ale pokaż zapowiedź dla postów, które są nieczytelne z powodu zwykłych ograniczeń prywatności lub ról.','If anyone tries to view a post they don\'t have access to, redirect to another post instead of displaying a teaser.'=>'Jeśli ktokolwiek spróbuje wyświetlić post, do którego nie ma dostępu, przekieruj do innego postu zamiast wyświetlać zapowiedź.','Replace post content or excerpt with custom text, possibly including an inline login form. You can also add text before or after the post title and excerpt.'=>'Zastąp treść lub fragment postu niestandardowym tekstem, być może zawierającym formularz logowania w linii. Możesz również dodać tekst przed lub po tytule postu i fragmencie.','Unreadable items of these comma-separated types will have nav menu item hidden.'=>'Nieczytelne elementy tych typów oddzielonych przecinkami będą miały ukryty element menu nawigacyjnego.','Visibility Circle membership does not limit viewing access.'=>'Członkostwo w Kręgu Widoczności nie ogranicza dostępu do przeglądania.','Editorial Circle membership does not limit editing access.'=>'Członkostwo w Kręgu Redakcyjnym nie ogranicza dostępu do edytowania.','When searching for users via Permissions ajax, return return only users registered to current site'=>'Podczas wyszukiwania użytkowników za pomocą ajaxa uprawnień, zwróć tylko użytkowników zarejestrowanych na bieżącej stronie','If user is a super admin or has \'pp_manage_network_members\' capability, user searches via Permissions ajax return users from all sites'=>'Jeśli użytkownik jest super administratorem lub ma zdolność \'pp_manage_network_members\', wyszukiwania użytkowników za pomocą ajaxa uprawnień zwracają użytkowników z wszystkich stron','Count users as a member of a BuddyPress Permissions Group only if they are a moderator of the BP group'=>'Liczyj użytkowników jako członków Grupy Uprawnień BuddyPress tylko wtedy, gdy są moderatorami grupy BP','Count users as a member of a BuddyPress Permissions Group only if they are an administrator of the BP group'=>'Liczyj użytkowników jako członków Grupy Uprawnień BuddyPress tylko wtedy, gdy są administratorami grupy BP','CMS Page Tree View plugin: hide \'add\' links (for all hierarchical post types) based on user\'s association permissions'=>'Wtyczka CMS Page Tree View: ukryj linki \'dodaj\' (dla wszystkich hierarchicznych typów postów) w zależności od uprawnień stowarzyszenia użytkownika','CMS Page Tree View plugin: hide \'add\' links (for pages) based on user\'s page association permissions'=>'Wtyczka CMS Page Tree View: ukryj linki \'dodaj\' (dla stron) w zależności od uprawnień stowarzyszenia strony użytkownika','CMS Page Tree View plugin: hide \'add\' links (for specified hierarchical post type) based on user\'s association permissions'=>'Wtyczka CMS Page Tree View: ukryj linki \'dodaj\' (dla określonego hierarchicznego typu postu) w zależności od uprawnień stowarzyszenia użytkownika','Prevent Permission from filtering the Nested Pages listing at all'=>'Zapobiegaj filtrowaniu listy stron zagnieżdżonych przez uprawnienia','Force Permissions to filter the Nested Pages listing'=>'Wymuś, aby uprawnienia filtrowały listę stron zagnieżdżonych','Comma-separated list of roles that are allowed to Quick Edit nested pages'=>'Lista ról oddzielona przecinkami, które mają prawo do szybkiej edycji stron zagnieżdżonych','Comma-separated list of roles that are allowed to use the Context Menu'=>'Lista ról oddzielona przecinkami, które mają prawo do korzystania z menu kontekstowego','Never allow unfiltered users to use the Context Menu, even if they have pp_force_quick_edit capability'=>'Nigdy nie pozwalaj użytkownikom bez filtrów na korzystanie z menu kontekstowego, nawet jeśli mają zdolność pp_force_quick_edit','Disable Add Child link unless user is unfiltered (Administrator or has pp_nested_pages_unfiltered capability)'=>'Wyłącz link Dodaj dziecko, chyba że użytkownik jest bez filtrów (Administrator lub ma zdolność pp_nested_pages_unfiltered)','Disable Add Child Page link unless user is unfiltered'=>'Wyłącz link Dodaj stronę potomną, chyba że użytkownik jest bez filtrów','Disable Insert Page Before link unless user is unfiltered'=>'Wyłącz link Wstaw stronę przed, chyba że użytkownik jest bez filtrów','Disable Insert Page After link unless user is unfiltered'=>'Wyłącz link Wstaw stronę po, chyba że użytkownik jest bez filtrów','Disable Push to Top link unless user is unfiltered'=>'Wyłącz link Przesuń na górę, chyba że użytkownik jest bez filtrów','Disable Push to Bottom link unless user is unfiltered'=>'Wyłącz link Przesuń na dół, chyba że użytkownik jest bez filtrów','Disable Clone link unless user is unfiltered'=>'Wyłącz link Klonuj, chyba że użytkownik jest bez filtrów','License'=>'Licencja','License Key'=>'Klucz licencyjny','Version'=>'Wersja','settings'=>'ustawienia','Key Expired'=>'Klucz wygasł','Deactivate Key'=>'Dezaktywuj klucz','Key Activated'=>'Klucz aktywowany','(please enter publishpress.com key)'=>'(proszę wprowadzić klucz publishpress.com)','Activate Key'=>'Aktywuj klucz','Note: Renewal does not require deactivation. If you do deactivate, re-entry of the license key will be required.'=>'Uwaga: Odnowienie nie wymaga dezaktywacji. Jeśli jednak zdezaktywujesz, ponowne wprowadzenie klucza licencyjnego będzie wymagane.','Your license key has expired. For continued priority support, %1$splease renew%2$s.'=>'Twój klucz licencyjny wygasł. Aby kontynuować priorytetowe wsparcie, %1$sproszę odnowić%2$s.','Your license key will expire today. For updates and priority support, %1$splease renew%2$s.'=>'Twój klucz licencyjny wygasa dzisiaj. Aby uzyskać aktualizacje i priorytetowe wsparcie, %1$sproszę odnowić%2$s.','Your license key (for plugin updates) will expire in %1$d day(s). For updates and priority support, %2$splease renew%3$s.'=>'Twój klucz licencyjny (do aktualizacji wtycz